fn solve(m: i8, d: i8) -> i8 {
    // Fixed month lengths for a non-leap year.
    const DAYS: [i32; 12] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

    let mi = (m as i32) - 1;          // 0-based index
    let leading = (d as i32) - 1;     // empty cells before day 1
    let days_in_month = DAYS[mi as usize];

    let total_cells = leading + days_in_month;

    // ceil(total_cells / 7) for positive integers: (x + 6) / 7
    let weeks = (total_cells + 6) / 7;

    weeks as i8
}

